import pytest
from candidate import incr_list

@pytest.mark.parametrize("input_list, expected", [
    ([1, 2, 3], [2, 3, 4]),
    ([5, 3, 5, 2, 3, 3, 9, 0, 123], [6, 4, 6, 3, 4, 4, 10, 1, 124]),
])
def test_incr_list_normal_cases(input_list, expected):
    assert incr_list(input_list) == expected

@pytest.mark.parametrize("input_list", [
    [],
    [None],
    [True],
    [False],
])
def test_incr_list_empty_and_none_cases(input_list):
    expected = [None] if input_list is None else input_list
    assert incr_list(input_list) == expected

@pytest.mark.parametrize("input_list", [
    ["a", "b", "c"],
    [1.5, 2.5],
    ["text", 1],
])
def test_incr_list_types(input_list):
    with pytest.raises(TypeError):
        incr_list(input_list)

@pytest.mark.parametrize("input_list", [
    [1],
    [1, 2, 3, 4, 5],
])
def test_incr_list_boundary_cases(input_list):
    for i in range(len(input_list)):
        assert incr_list(input_list) == [i + 1] + input_list[i + 1:]
